// ── Unit under test ──────────────────────────────────────────────
function calculateDiscount(price, memberType) {
  if (price < 0) throw new Error('Price must be non-negative');
  const rates = { standard: 0, premium: 0.10, vip: 0.25 };
  const rate = rates[memberType];
  if (rate === undefined) throw new Error(`Unknown member type: ${memberType}`);
  return parseFloat((price * (1 - rate)).toFixed(2));
}

// ── Jest test suite (TDD: these tests were written FIRST) ────────
describe('calculateDiscount', () => {
  // Happy paths
  it('applies no discount for standard members', () => {
    expect(calculateDiscount(100, 'standard')).toBe(100);
  });

  it('applies 10% discount for premium members', () => {
    expect(calculateDiscount(100, 'premium')).toBe(90);
  });

  it('applies 25% discount for vip members', () => {
    expect(calculateDiscount(200, 'vip')).toBe(150);
  });

  // Edge case: floating-point rounding
  it('rounds to 2 decimal places', () => {
    // 33.33 * 0.90 = 29.997 → rounds to 30.00
    expect(calculateDiscount(33.33, 'premium')).toBe(30);
  });

  // Error paths
  it('throws for negative price', () => {
    expect(() => calculateDiscount(-10, 'standard'))
      .toThrow('Price must be non-negative');
  });

  it('throws for unknown member type', () => {
    expect(() => calculateDiscount(100, 'gold'))
      .toThrow('Unknown member type: gold');
  });
});

// ── Mock: isolate OrderService from real HTTP ────────────────────
class OrderService {
  constructor(httpClient) { this._http = httpClient; }
  async fetchOrder(id) {
    const res = await this._http.get(`/orders/${id}`);
    return res.data;
  }
}

// In the test — no real HTTP request is made
const mockHttp = {
  get: jest.fn().mockResolvedValue({ data: { id: 1, status: 'paid' } })
};
const svc = new OrderService(mockHttp);

test('fetchOrder returns the order data', async () => {
  const order = await svc.fetchOrder(1);
  expect(order.status).toBe('paid');
  expect(mockHttp.get).toHaveBeenCalledWith('/orders/1');
});

// ── TDD walkthrough: building a shopping cart step by step ──────

// ITERATION 1 ─────────────────────────────────────────────────
// RED: write this test first; it fails (Cart doesn't exist yet)
test('an empty cart has total 0', () => {
  const cart = new Cart();
  expect(cart.total()).toBe(0);
});

// GREEN: minimum code to pass
class Cart {
  total() { return 0; }
}

// ITERATION 2 ─────────────────────────────────────────────────
// RED: new test fails (total is hardcoded to 0)
test('adding one item updates the total', () => {
  const cart = new Cart();
  cart.add({ name: 'Widget', price: 9.99 });
  expect(cart.total()).toBeCloseTo(9.99);
});

// GREEN: extend implementation
class Cart {
  constructor() { this._items = []; }
  add(item) { this._items.push(item); }
  total() { return this._items.reduce((sum, i) => sum + i.price, 0); }
}

// ITERATION 3 ─────────────────────────────────────────────────
// RED: quantity support
test('adding multiple quantities sums correctly', () => {
  const cart = new Cart();
  cart.add({ name: 'Widget', price: 9.99, qty: 3 });
  expect(cart.total()).toBeCloseTo(29.97);
});

// GREEN: handle qty
class Cart {
  constructor() { this._items = []; }
  add(item) { this._items.push({ ...item, qty: item.qty || 1 }); }
  total() {
    return this._items.reduce((sum, i) => sum + i.price * i.qty, 0);
  }
}

// REFACTOR: extract the line-item calculation
class Cart {
  constructor() { this._items = []; }
  add(item) { this._items.push({ ...item, qty: item.qty ?? 1 }); }
  _lineTotal(item) { return item.price * item.qty; }
  total() { return this._items.reduce((sum, i) => sum + this._lineTotal(i), 0); }
}

