// ── Spy: observe real calls without replacing implementation ──────
const emailService = {
  send: (to, subject, body) => {
    // real implementation would call an SMTP server
    console.log(`Sent "${subject}" to ${to}`);
  }
};

// Wrap the real method to track calls
const spy = jest.spyOn(emailService, 'send');

// Exercise the system under test
const orderService = new OrderService(emailService);
orderService.placeOrder({ email: 'alice@example.com', amount: 49.99 });

// Assert the collaboration happened correctly
expect(spy).toHaveBeenCalledTimes(1);
expect(spy).toHaveBeenCalledWith(
  'alice@example.com',
  expect.stringContaining('Order Confirmation'),
  expect.stringContaining('49.99')
);

// The real send() still ran — no stub needed here
spy.mockRestore(); // clean up after the test

